package com.shanjay.mart.dao;
import com.shanjay.mart.model.User; import java.sql.*; import javax.sql.DataSource;
public class UserDAO { private final DataSource ds; public UserDAO(DataSource ds){this.ds=ds;} public User findByEmail(String email)throws SQLException{String q="SELECT * FROM users WHERE email=?"; try(Connection c=ds.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,email);try(ResultSet r=p.executeQuery()){if(r.next())return map(r);}}return null;} public boolean emailExists(String e)throws SQLException{return findByEmail(e)!=null;} public void create(String n,String e,String h,String role)throws SQLException{try(Connection c=ds.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)")){p.setString(1,n);p.setString(2,e);p.setString(3,h);p.setString(4,role);p.executeUpdate();}} public java.util.List<User> all()throws SQLException{var out=new java.util.ArrayList<User>();try(Connection c=ds.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM users ORDER BY id");ResultSet r=p.executeQuery()){while(r.next())out.add(map(r));}return out;} private User map(ResultSet r)throws SQLException{return new User(r.getLong("id"),r.getString("name"),r.getString("email"),r.getString("password_hash"),r.getString("role"));}}
